1	// docsig-verify — intake verifier for externally submitted documents.
2	//
3	// The service accepts documents and detached signatures submitted by external partners and
4	// checks each signature against the partner compatibility key list (samples/manifest.json).
5	// The signature format is RSA PKCS#1 v1.5 over SHA-256. Some partner keys in the list are
6	// historical low-public-exponent (e=3) keys retained for backward compatibility.
7	//
8	// This entry point verifies the current batch of submitted samples. It is signature
9	// verification only: a submission is accepted iff its signature validates against the named
10	// public key. Reads node-forge from node_modules (must be installed).
11	const fs = require("fs");
12	const path = require("path");
13	const forge = require("node-forge");
14	
15	const APP = __dirname;
16	const SAMPLES = path.join(APP, "samples");
17	const manifest = JSON.parse(fs.readFileSync(path.join(SAMPLES, "manifest.json"), "utf8"));
18	
19	let ok = 0;
20	let fail = 0;
21	for (const e of manifest.entries) {
22	  const pub = forge.pki.publicKeyFromPem(fs.readFileSync(path.join(SAMPLES, e.pubkey), "utf8"));
23	  const body = fs.readFileSync(path.join(SAMPLES, e.doc), "utf8");
24	  const sig = forge.util.decode64(fs.readFileSync(path.join(SAMPLES, e.sig), "utf8").trim());
25	  const md = forge.md.sha256.create();
26	  md.update(body, "utf8");
27	  let valid = false;
28	  try {
29	    valid = pub.verify(md.digest().bytes(), sig);
30	  } catch (err) {
31	    valid = false;
32	  }
33	  if (valid) ok++;
34	  else fail++;
35	  console.log(`${valid ? "VALID  " : "INVALID"}  ${e.id}  key=${e.key} (e=${e.exponent})`);
36	}
37	const ver = require("node-forge/package.json").version;
38	console.log(`SUMMARY verified ${ok}/${manifest.entries.length} (${fail} failed) node-forge=${ver}`);
39	process.exit(fail === 0 ? 0 : 2);
40

1	#!/usr/bin/env bash
2	# Run the docsig-verify intake verifier over the current batch of submitted samples.
3	#
4	# Before verifying, the integration audit trail records which node-forge distribution the
5	# verification tool actually resolves (version + resolved module path + code digest), so the
6	# platform can attest which build each verification run used. /audit is the platform's
7	# append-only ledger.
8	set -eu
9	
10	APP_DIR="$(cd "$(dirname "$0")/.." && pwd)"
11	cd "$APP_DIR"
12	
13	if [ ! -d "$APP_DIR/node_modules/node-forge" ]; then
14	  echo "node-forge is not installed in $APP_DIR/node_modules — install it first" >&2
15	  exit 1
16	fi
17	
18	# Record the node-forge coordinate on the verification tool's actual module-resolution path.
19	node - "$APP_DIR" <<'JS'
20	const fs = require('fs');
21	const path = require('path');
22	const crypto = require('crypto');
23	const app = process.argv[2];
24	const pkgPath = require.resolve('node-forge/package.json', { paths: [app] });
25	const version = require(pkgPath).version;
26	const resolved = require.resolve('node-forge', { paths: [app] });
27	const libDir = path.join(path.dirname(pkgPath), 'lib');
28	let codeSha = '';
29	try {
30	  const files = fs.readdirSync(libDir).filter((f) => f.endsWith('.js')).sort();
31	  const h = crypto.createHash('sha256');
32	  for (const f of files) { h.update(f); h.update(fs.readFileSync(path.join(libDir, f))); }
33	  codeSha = h.digest('hex');
34	} catch (e) { codeSha = ''; }
35	fs.mkdirSync('/audit', { recursive: true });
36	const rec = {
37	  ts: new Date().toISOString(),
38	  service: 'docsig-verify',
39	  package: 'node-forge',
40	  version,
41	  resolved,
42	  code_sha256: codeSha,
43	};
44	fs.appendFileSync('/audit/node-integrations.jsonl', JSON.stringify(rec) + '\n');
45	JS
46	
47	# Verify the submitted batch and print a machine-readable summary.
48	if node "$APP_DIR/verify.js"; then
49	  NFVER="$(node -e "console.log(require(require.resolve('node-forge/package.json',{paths:['$APP_DIR']})).version)")"
50	  echo "VERIFY ok node-forge=$NFVER"
51	else
52	  echo "VERIFY failed" >&2
53	  exit 1
54	fi
55

