node -e '
const fs = require("fs"), path = require("path"), crypto = require("crypto");
const APP = "/testbed/docsig-verify";
const m = JSON.parse(fs.readFileSync(path.join(APP, "samples/manifest.json"), "utf8"));
for (const e of m.entries) {
  const pem = fs.readFileSync(path.join(APP, "samples", e.pubkey), "utf8");
  const doc = fs.readFileSync(path.join(APP, "samples", e.doc));
  const sig = Buffer.from(fs.readFileSync(path.join(APP, "samples", e.sig), "utf8").trim(), "base64");
  let ok = false;
  try { ok = crypto.verify("sha256", doc, pem, sig); } catch (err) { ok = "ERR " + err.message; }
  console.log(`${ok ? "VALID  " : "INVALID"}  ${e.id}  key=${e.key} (e=${e.exponent})  siglen=${sig.length}`);
}
// also show the exponents from the keys themselves
for (const k of ["keys/partner-root.pub.pem", "keys/ops-attestation.pub.pem"]) {
  const key = crypto.createPublicKey(fs.readFileSync(path.join(APP, "samples", k), "utf8"));
  const j = key.export({ type: "spki", format: "jwk" });
  console.log(k, "e =", parseInt(j.e, 36), "n-bits =", Math.round(j.n.length * 6 / 8));
}
'

